CREATE OR REPLACE FUNCTION public.features_for_plan(p_plan text) RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT CASE p_plan
WHEN 'free' THEN ARRAY['orchestrator_mode','marketplace_publish','a2a_publish','chat_widget']::text[]
WHEN 'pro' THEN ARRAY['orchestrator_mode','marketplace_publish','a2a_publish','chat_widget','prompt_history','advanced_analytics','file_attachments','advanced_webhooks','team_triggers','billing','messaging_channels','custom_tools']::text[]
WHEN 'team' THEN ARRAY['orchestrator_mode','marketplace_publish','a2a_publish','chat_widget','prompt_history','advanced_analytics','file_attachments','advanced_webhooks','team_triggers','billing','messaging_channels','custom_tools','collaboration_mode','team_memory','rbac']::text[]
WHEN 'enterprise' THEN ARRAY['orchestrator_mode','marketplace_publish','a2a_publish','chat_widget','prompt_history','advanced_analytics','file_attachments','advanced_webhooks','team_triggers','billing','messaging_channels','custom_tools','collaboration_mode','team_memory','rbac','audit_logs','swarm','admin_panel']::text[]
ELSE ARRAY[]::text[] END $$;
